/* @lc app=leetcode id=2467 lang=kotlin */ class Solution { fun inc(bt: IntArray, amt: IntArray, v: Int, d: Int) = if (bt[v] < d) 0 else if (bt[v] == d) amt[v] / 2 else amt[v] fun mostProfitablePath(edges: Array<IntArray>, bob: Int, amount: IntArray): Int = amount.size.let { n -> edges.flatMap { (a, b) -> listOf(a to b, b to a) }.groupBy({ it.first }, { it.second }).let { g -> IntArray(n) { -1 }.also { it[0] = 0 }.let { par -> generateSequence(listOf(0)) { f -> f.flatMap { u -> g[u].orEmpty().filter { v -> par[v] == -1 }.onEach { v -> par[v] = u } }.takeIf { it.isNotEmpty() } }.count().let { IntArray(n) { Int.MAX_VALUE }.also { bt -> generateSequence(bob) { if (it == 0) null else par[it] }.forEachIndexed { t, v -> bt[v] = t } }.let { bt -> generateSequence(listOf(0 to inc(bt, amount, 0, 0)) to 0) { (f, d) -> f.flatMap { (v, s) -> g[v].orEmpty().filter { it != par[v] }.map { c -> c to s + inc(bt, amount, c, d + 1) } }.takeIf { it.isNotEmpty() }?.let { it to d + 1 } }.map { it.first }.flatten().filter { (v, _) -> v != 0 && g[v]!!.size == 1 }.maxOf { it.second } } } } } } }